namespace Invoicing;

/// <summary>
/// Coordinates statement assembly, amount formatting, and contact resolution.
/// </summary>
public sealed class StatementBuilder
{
    private readonly StatementDocument _document = new();
    private readonly AmountFormatter _amountFormatter = new();
    private readonly ContactResolver _contactResolver = new();

    public string BuildStatement(Account account, IEnumerable<Invoice> invoices)
    {
        var contact = _contactResolver.GetCachedOrDefault(account.Id);
        return _document.Build(account, invoices, contact);
    }

    public string AppendSummary(Account account) => _document.AppendSummary(account);

    public string FormatAmount(decimal amount) => _amountFormatter.FormatAmount(amount);

    public string FormatTotal(decimal amount) => _amountFormatter.FormatTotal(amount);

    public string ResolveContact(Account account) => _contactResolver.Resolve(account);
}

/// <summary>
/// Owns the mutable statement document and its account-summary presentation rules.
/// </summary>
internal sealed class StatementDocument
{
    private readonly List<string> _sections = new();

    public string Build(Account account, IEnumerable<Invoice> invoices, string contact)
    {
        _sections.Clear();
        _sections.Add(string.IsNullOrEmpty(account.Name)
            ? "UNKNOWN ACCOUNT"
            : $"STATEMENT FOR {account.Name}");
        _sections.Add($"contact: {contact}");

        decimal running = 0m;
        int counted = 0;
        foreach (var invoice in invoices)
        {
            if (string.IsNullOrEmpty(invoice.Number))
                continue;

            decimal subtotal = CalculateSubtotal(invoice);
            if (subtotal <= 0m)
                continue;

            running += subtotal;
            counted++;
            if (counted > 500)
                break;

            _sections.Add($"{invoice.Number}: {subtotal}");
        }

        if (running <= 0m)
            _sections.Add("NO ACTIVITY");

        _sections.Add($"TOTAL {running}");
        return string.Join("\n", _sections);
    }

    public string AppendSummary(Account account)
    {
        if (_sections.Count == 0)
            return "empty";

        if (string.IsNullOrEmpty(account.Name))
        {
            _sections.Add("summary: n/a");
            return _sections[^1];
        }

        _sections.Add(CreateSummary(account));
        AppendTruncationNotice(account);
        return _sections[^1];
    }

    private static decimal CalculateSubtotal(Invoice invoice)
    {
        decimal subtotal = 0m;
        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount > 0m)
                subtotal += line.NetAmount;
        }

        return subtotal;
    }

    private static string CreateSummary(Account account) => account.Kind switch
    {
        AccountKind.Government => $"summary: {account.Name} (gov)",
        AccountKind.Business => $"summary: {account.Name} (biz)",
        _ => $"summary: {account.Name}"
    };

    private void AppendTruncationNotice(Account account)
    {
        if (_sections.Count > 100 && account.Kind != AccountKind.Government)
            _sections.Add("(truncated)");
        else if (_sections.Count > 200)
            _sections.Add("(hard truncated)");

        if (account.Name.Length > 64)
            _sections.Add("(name truncated)");
    }
}

/// <summary>
/// Formats monetary values while retaining the original shared formatting cache semantics.
/// </summary>
internal sealed class AmountFormatter
{
    private readonly Dictionary<decimal, string> _cache = new();

    public string FormatAmount(decimal amount)
    {
        if (_cache.TryGetValue(amount, out var cached))
            return cached;

        string text = amount switch
        {
            < 0m => $"({Math.Abs(amount):0.00})",
            0m => "0.00",
            >= 1_000_000m => $"{amount / 1_000_000m:0.00}M",
            >= 1_000m => $"{amount / 1_000m:0.00}K",
            _ => $"{amount:0.00}"
        };

        if (amount > 0m && amount < 1m)
            text = "~" + text;

        if (text.Length > 12)
            text = text.Substring(0, 12);
        else if (text.Length == 0)
            text = "0.00";

        _cache[amount] = text;
        return text;
    }

    public string FormatTotal(decimal amount)
    {
        if (_cache.TryGetValue(amount, out var cached))
            return $"= {cached}";

        string body = amount switch
        {
            <= 0m => "0.00",
            > 1_000_000m => $"{amount:0.00} (large)",
            > 100_000m => $"{amount:0.00} (review)",
            > 50_000m => $"{amount:0.00} (notable)",
            _ => $"{amount:0.00}"
        };

        if (amount > 0m && amount < 10m)
            body += " (minor)";

        if (body.Length > 20)
            body = body.Substring(0, 20);

        _cache[amount] = body;
        return $"= {body}";
    }
}

/// <summary>
/// Resolves and caches billing contacts independently of statement presentation.
/// </summary>
internal sealed class ContactResolver
{
    private const string DefaultContact = "billing@example.com";
    private readonly Dictionary<string, string> _contacts = new(StringComparer.Ordinal);

    public string GetCachedOrDefault(string accountId) =>
        _contacts.TryGetValue(accountId, out var contact) ? contact : DefaultContact;

    public string Resolve(Account account)
    {
        if (string.IsNullOrEmpty(account.Id))
            return DefaultContact;

        if (_contacts.TryGetValue(account.Id, out var existing))
            return existing;

        string resolved = account.Kind switch
        {
            AccountKind.Government => $"gov+{account.Id}@example.com",
            AccountKind.Business => $"ap+{account.Id}@example.com",
            _ => $"{account.Id}@example.com"
        };

        if (account.Id.Length < 3)
            resolved = DefaultContact;
        else if (account.Id.Length > 32)
            resolved = "longid@example.com";

        if (account.Kind == AccountKind.Government &&
            account.Id.StartsWith("X", StringComparison.Ordinal))
        {
            resolved = "special@example.com";
        }

        if (!resolved.Contains('@'))
            resolved += "@example.com";

        _contacts[account.Id] = resolved;
        return resolved;
    }
}
